def semver_sort(versions):
    def parse_version(version):
        # Split version and build metadata
        if '+' in version:
            version_part, build = version.split('+', 1)
        else:
            version_part = version
            build = ""

        # Split core version and pre-release
        if '-' in version_part:
            core, prerelease = version_part.split('-', 1)
        else:
            core = version_part
            prerelease = None

        # Parse core version (MAJOR.MINOR.PATCH)
        parts = core.split('.')
        major = int(parts[0])
        minor = int(parts[1]) if len(parts) > 1 else 0
        patch = int(parts[2]) if len(parts) > 2 else 0

        # Parse pre-release identifiers
        if prerelease:
            prerelease_ids = prerelease.split('.')
            # Convert all-digit identifiers to integers for comparison
            prerelease_parsed = []
            for id in prerelease_ids:
                if id.isdigit():
                    prerelease_parsed.append((0, int(id)))  # 0 means numeric, sorts first
                else:
                    prerelease_parsed.append((1, id))  # 1 means string, sorts after
        else:
            prerelease_parsed = None

        return (major, minor, patch, prerelease_parsed)

    def sort_key(item):
        version_str, index = item
        major, minor, patch, prerelease_parsed = parse_version(version_str)

        # Create sort key:
        # - Core version (major, minor, patch)
        # - If has prerelease: (0, prerelease_parsed) - pre-release sorts before release
        # - If no prerelease: (1, ()) - release sorts after pre-release
        # - Original index for stable sort (versions of equal precedence keep input order)

        if prerelease_parsed is not None:
            return (major, minor, patch, 0, prerelease_parsed, index)
        else:
            return (major, minor, patch, 1, (), index)

    # Sort with original indices to maintain order for equal precedence
    indexed_versions = list(enumerate(versions))
    sorted_versions = sorted(indexed_versions, key=sort_key)

    return [v for _, v in sorted_versions]

